typedef long long ll;

typedef struct {
    int *v;
    int sz, cap;
} Vec;

static void vec_init(Vec *a) {
    a->v = NULL;
    a->sz = 0;
    a->cap = 0;
}
static void vec_push(Vec *a, int x) {
    if (a->sz == a->cap) {
        a->cap = a->cap ? a->cap * 2 : 4;
        a->v = (int*)realloc(a->v, a->cap * sizeof(int));
    }
    a->v[a->sz++] = x;
}

typedef struct {
    int n;
    Vec *g;
} Graph;

static Graph make_graph(int n) {
    Graph gr;
    gr.n = n;
    gr.g = (Vec*)malloc((n + 1) * sizeof(Vec));
    for (int i = 0; i <= n; i++) vec_init(&gr.g[i]);
    return gr;
}
static void add_edge(Graph *gr, int u, int v) {
    vec_push(&gr->g[u], v);
    vec_push(&gr->g[v], u);
}

static int n;
static Graph gr;
static int *parent_;
static int *depth_;
static int *order_;
static int ord_sz;

static void build_rooted(int root) {
    int *q = (int*)malloc((n + 5) * sizeof(int));
    int qh = 0, qt = 0;
    q[qt++] = root;
    parent_[root] = 0;
    depth_[root] = 0;
    ord_sz = 0;
    while (qh < qt) {
        int u = q[qh++];
        order_[ord_sz++] = u;
        for (int i = 0; i < gr.g[u].sz; i++) {
            int v = gr.g[u].v[i];
            if (v == parent_[u]) continue;
            parent_[v] = u;
            depth_[v] = depth_[u] + 1;
            q[qt++] = v;
        }
    }
    free(q);
}

/*
Core idea:

For a rooted tree, consider "completion" by adding children so that all vertices
of the same color have identical multiset of children colors.

Minimal number of colors equals height+1 for an optimally chosen root at a center,
because each depth must differ from adjacent depths, and all vertices on same depth
can share a color after completion.

For fixed root:
Let need[d] = maximum number of children among vertices at depth d.
Then every vertex at depth d must be completed to have exactly need[d] children,
all of color of depth d+1 (except deepest level with 0 children).

Leaves in the completed tree:
- All vertices at maximum depth H are leaves.
- Any vertex at depth d < H becomes non-leaf iff need[d] > 0.
Thus only depths with need[d] = 0 contribute leaves, but if d < H that means all
vertices at depth d are leaves, forcing H=d. So for a rooted connected tree,
for d < H there exists some vertex at depth d+1, hence some vertex at depth d has child,
thus need[d] > 0.
Therefore leaves count in the completed rooted tree is:
    number of vertices at maximum depth H, plus added vertices propagated by completion.

We compute bottom-up:
Let F[d] = number of leaves in the completed canonical subtree rooted at any vertex
of depth d (all such completed subtrees are identical).
Then:
    F[H] = 1
    F[d] = need[d] * F[d+1]
because every vertex at depth d has exactly need[d] children after completion,
each child roots an identical completed subtree with F[d+1] leaves.

Total leaves for the whole completed tree rooted at r is F[0].

Need array depends on root. Minimal colorfulness is radius+1, so roots to consider
are tree centers (one or two). We compute F[0] for each center and take minimum.
*/

static int bfs_far(int src, int *dist, int *par) {
    int *q = (int*)malloc((n + 5) * sizeof(int));
    for (int i = 1; i <= n; i++) dist[i] = -1;
    int qh = 0, qt = 0;
    q[qt++] = src;
    dist[src] = 0;
    par[src] = 0;
    int last = src;
    while (qh < qt) {
        int u = q[qh++];
        last = u;
        for (int i = 0; i < gr.g[u].sz; i++) {
            int v = gr.g[u].v[i];
            if (dist[v] != -1) continue;
            dist[v] = dist[u] + 1;
            par[v] = u;
            q[qt++] = v;
        }
    }
    free(q);
    return last;
}

static ll solve_for_root(int root) {
    build_rooted(root);

    int H = 0;
    for (int i = 0; i < ord_sz; i++) {
        int u = order_[i];
        if (depth_[u] > H) H = depth_[u];
    }

    int *cntDepth = (int*)calloc(H + 1, sizeof(int));
    int *need = (int*)calloc(H + 1, sizeof(int));
    int *childcnt = (int*)calloc(n + 1, sizeof(int));

    for (int i = 0; i < ord_sz; i++) {
        int u = order_[i];
        cntDepth[depth_[u]]++;
    }
    for (int i = 0; i < ord_sz; i++) {
        int u = order_[i];
        int c = 0;
        for (int j = 0; j < gr.g[u].sz; j++) {
            int v = gr.g[u].v[j];
            if (v != parent_[u]) c++;
        }
        childcnt[u] = c;
        if (depth_[u] < H && c > need[depth_[u]]) need[depth_[u]] = c;
    }

    ll *F = (ll*)malloc((H + 1) * sizeof(ll));
    F[H] = 1;
    for (int d = H - 1; d >= 0; d--) {
        F[d] = (ll)need[d] * F[d + 1];
    }

    ll ans = F[0];

    free(cntDepth);
    free(need);
    free(childcnt);
    free(F);
    return ans;
}

int main(void) {
    if (scanf("%d", &n) != 1) return 0;
    gr = make_graph(n);
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        add_edge(&gr, u, v);
    }

    if (n == 1) {
        printf("1 1\n");
        return 0;
    }

    parent_ = (int*)malloc((n + 1) * sizeof(int));
    depth_ = (int*)malloc((n + 1) * sizeof(int));
    order_ = (int*)malloc((n + 1) * sizeof(int));

    int *dist1 = (int*)malloc((n + 1) * sizeof(int));
    int *dist2 = (int*)malloc((n + 1) * sizeof(int));
    int *par = (int*)malloc((n + 1) * sizeof(int));

    int a = bfs_far(1, dist1, par);
    int b = bfs_far(a, dist1, par);

    int diameter = dist1[b];
    int *path = (int*)malloc((diameter + 1) * sizeof(int));
    int len = 0;
    int cur = b;
    while (cur) {
        path[len++] = cur;
        if (cur == a) break;
        cur = par[cur];
    }

    int colorfulness = diameter / 2 + 1; /* radius + 1 */

    ll bestLeaves;
    if (diameter % 2 == 0) {
        int center = path[diameter / 2];
        bestLeaves = solve_for_root(center);
    } else {
        int c1 = path[diameter / 2];
        int c2 = path[diameter / 2 + 1];
        ll x = solve_for_root(c1);
        ll y = solve_for_root(c2);
        bestLeaves = x < y ? x : y;
    }

    printf("%d %lld\n", colorfulness, bestLeaves);

    free(path);
    free(dist1);
    free(dist2);
    free(par);
    free(parent_);
    free(depth_);
    free(order_);
    for (int i = 0; i <= n; i++) free(gr.g[i].v);
    free(gr.g);

    return 0;
}

