vector<int> find_centers() {
    vector<int> leaves;
    vector<int> deg = degree;
    queue<int> q;
    for (int i = 0; i < n; i++) {
        if (deg[i] <= 1) {
            q.push(i);
        }
    }
    int remaining = n;
    while (remaining > 2) {
        int sz = q.size();
        while (sz--) {
            int u = q.front(); q.pop();
            remaining--;
            for (int v : adj[u]) {
                if (--deg[v] == 1) {
                    q.push(v);
                }
            }
        }
    }
    vector<int> centers;
    while (!q.empty()) {
        centers.push_back(q.front());
        q.pop();
    }
    return centers;
}

