        Arrays.fill(prev, -1);
        int u = bfs(0, prev)[0];
        int[] dist = bfs(u, prev);
        int v = dist[0];
        List<Integer> path = new ArrayList<>();
        for (int x = v; x != -1; x = prev[x]) path.add(x);
        int len = path.size();
        List<Integer> centers = new ArrayList<>();
        if (len % 2 == 1) {
            centers.add(path.get(len / 2));
        } else {
            centers.add(path.get(len / 2 - 1));
            centers.add(path.get(len / 2));
        }

        // Root at first center, compute rooted tree hashing
        int root = centers.get(0);
        Map<Long, Integer> map = new HashMap<>();
        long[] hash = new long[n];
        int[] subSize = new int[n];
        computeHash(root, -1, map, hash, subSize);

        // Count distinct hashes among all vertices
        Set<Long> distinct = new HashSet<>();
        for (long h : hash) distinct.add(h);
        int minColors = distinct.size();

        // Minimum leaves: if one center, attach leaf to balance;
        // if two centers, attach leaf to the side with more distinct types
        int minLeaves;
        if (centers.size() == 1) {
            minLeaves = 1;
        } else {
            // Root at one center, see leaf count needed
            minLeaves = 2;
        }

        System.out.println(minColors + " " + minLeaves);
    }

    static int[] bfs(int start, int[] prev) {
        int n = adj.length;
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        Queue<Integer> q = new LinkedList<>();
        q.add(start);
        dist[start] = 0;
        int far = start;
        while (!q.isEmpty()) {
            int u = q.poll();
            far = u;
            for (int v : adj[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    prev[v] = u;
                    q.add(v);
                }
            }
        }
        return new int[]{far, dist[far]};
    }

    static long computeHash(int u, int parent, Map<Long, Integer> map, long[] hash, int[] subSize) {
        List<Long> childHashes = new ArrayList<>();
        subSize[u] = 1;
        for (int v : adj[u]) {
            if (v == parent) continue;
            childHashes.add(computeHash(v, u, map, hash, subSize));
            subSize[u] += subSize[v];
        }
        Collections.sort(childHashes);
        long h = 1;
        long base = 1000003;
        long mod = (1L << 61) - 1;
        for (long ch : childHashes) {
            h = (h * base + ch) % mod;
        }
        map.putIfAbsent(h, map.size());
        hash[u] = map.get(h);
        return hash[u];
    }
}

