public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sgn = 1;
            if (c == '-') { sgn = -1; c = read(); }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sgn;
        }
    }

    static class Profile {
        int[] a; // branching factors by depth
        Profile(int[] a) { this.a = a; }
    }

    static int n;
    static ArrayList<Integer>[] g;

    static Profile buildForRoot(int root) {
        int[] parent = new int[n];
        Arrays.fill(parent, -2);
        int[] order = new int[n];
        int sz = 0;
        parent[root] = -1;
        order[sz++] = root;
        for (int i = 0; i < sz; i++) {
            int v = order[i];
            for (int to : g[v]) {
                if (parent[to] == -2) {
                    parent[to] = v;
                    order[sz++] = to;
                }
            }
        }

        Profile[] dp = new Profile[n];
        for (int i = n - 1; i >= 0; i--) {
            int v = order[i];
            int childCount = 0;
            int maxLen = 0;
            for (int to : g[v]) {
                if (to == parent[v]) continue;
                childCount++;
                maxLen = Math.max(maxLen, dp[to].a.length);
            }
            if (childCount == 0) {
                dp[v] = new Profile(new int[0]);
            } else {
                int[] merged = new int[maxLen];
                for (int to : g[v]) {
                    if (to == parent[v]) continue;
                    int[] p = dp[to].a;
                    for (int j = 0; j < p.length; j++) {
                        if (p[j] > merged[j]) merged[j] = p[j];
                    }
                }
                int[] cur = new int[maxLen + 1];
                cur[0] = childCount;
                System.arraycopy(merged, 0, cur, 1, maxLen);
                dp[v] = new Profile(cur);
            }
        }
        return dp[root];
    }

    static BigInteger leaves(Profile p) {
        BigInteger ans = BigInteger.ONE;
        for (int x : p.a) ans = ans.multiply(BigInteger.valueOf(x));
        return ans;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        n = fs.nextInt();
        g = new ArrayList[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            int u = fs.nextInt() - 1;
            int v = fs.nextInt() - 1;
            g[u].add(v);
            g[v].add(u);
        }

        int bestColors = Integer.MAX_VALUE;
        BigInteger bestLeaves = null;

        for (int r = 0; r < n; r++) {
            Profile p = buildForRoot(r);
            int colors = p.a.length + 1;
            BigInteger lf = leaves(p);
            if (colors < bestColors || (colors == bestColors && (bestLeaves == null || lf.compareTo(bestLeaves) < 0))) {
                bestColors = colors;
                bestLeaves = lf;
            }
        }

        System.out.println(bestColors + " " + bestLeaves);
    }
}
